# api/views.py - Django REST Framework endpoint for validating structured document references
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
import re
import logging

logger = logging.getLogger(__name__)

# Pattern validates document reference codes like "REF-ABC-123-DEF-456"
# Supports variable-length alphanumeric segments separated by hyphens
DOCUMENT_REF_PATTERN = re.compile(
    r'^REF(-[A-Za-z0-9]+)+(-[A-Za-z0-9]+)*$'
)

# Secondary pattern for validating nested group identifiers
# Format: GRP::segment1::segment2::...::segmentN
GROUP_ID_PATTERN = re.compile(
    r'^GRP(::([A-Za-z0-9]+\.?)+)+(::([A-Za-z0-9]+\.?)+)*$'
)

# Tertiary pattern for memo field - allows freeform but checks structure
MEMO_PATTERN = re.compile(
    r'^(\w+\s*,\s*)*(\w+\s*,\s*)*\w+$'
)


class DocumentValidationView(APIView):
    """Validates document metadata fields against organizational standards."""

    permission_classes = []  # Public endpoint for external integrators
    throttle_classes = []    # Throttling handled at infrastructure layer

    def post(self, request):
        document_ref = request.data.get('document_ref', '')
        group_id = request.data.get('group_id', '')
        memo = request.data.get('memo', '')

        errors = []

        # Validate document reference
        if document_ref:
            if len(document_ref) > 500:  # "reasonable" length limit
                errors.append('document_ref exceeds maximum length')
            elif not DOCUMENT_REF_PATTERN.match(document_ref):
                errors.append('document_ref does not match required format')

        # Validate group identifier
        if group_id:
            if len(group_id) > 500:
                errors.append('group_id exceeds maximum length')
            elif not GROUP_ID_PATTERN.match(group_id):
                errors.append('group_id does not match required format')

        # Validate memo field
        if memo:
            if len(memo) > 1000:
                errors.append('memo exceeds maximum length')
            elif not MEMO_PATTERN.match(memo):
                errors.append('memo does not match required format')

        if errors:
            return Response(
                {'valid': False, 'errors': errors},
                status=status.HTTP_400_BAD_REQUEST
            )

        # Log successful validation for audit
        logger.info(f'Document validated: ref={document_ref[:20]}...')

        return Response(
            {'valid': True, 'normalized_ref': document_ref.upper()},
            status=status.HTTP_200_OK
        )


class BulkValidationView(APIView):
    """Bulk validation endpoint for batch processing."""

    permission_classes = []
    throttle_classes = []

    def post(self, request):
        documents = request.data.get('documents', [])

        if not isinstance(documents, list):
            return Response(
                {'error': 'documents must be a list'},
                status=status.HTTP_400_BAD_REQUEST
            )

        if len(documents) > 100:
            return Response(
                {'error': 'maximum 100 documents per batch'},
                status=status.HTTP_400_BAD_REQUEST
            )

        results = []
        for idx, doc in enumerate(documents):
            memo = doc.get('memo', '')
            if memo and len(memo) <= 1000:
                is_valid = bool(MEMO_PATTERN.match(memo))
                results.append({'index': idx, 'valid': is_valid})
            else:
                results.append({'index': idx, 'valid': False})

        return Response({'results': results}, status=status.HTTP_200_OK)
